      const top = { kind: 'std', name: 'top' };
      const sk = (draw) => { const s = F.createFeature(plate, 'sketch', { plane: top, ...S.createSketchGeometry() }); draw(s); plate.features.push(s); return s; };
      const base = sk((k) => S.addRectangle(k, 0, 0, 120, 60));
      plate.features.push(F.createFeature(plate, 'extrude', { sketch: base.id, depth: 5 }));
      const hs = sk((k) => S.addCircle(k, 10, 10, 2));
      const hole = F.createFeature(plate, 'extrude', { sketch: hs.id, op: 'cut', end: 'throughBoth' });
      plate.features.push(hole);
      plate.features.push(F.createFeature(plate, 'linearPattern', { seeds: [hole.id], direction: { kind: 'axis', axis: 'x' }, spacing: 25, count: 4 }));
      const pts = sk((k) => { for (const [x, y] of [[10, 50], [40, 50], [70, 45]]) { const p = { id: S.newSketchId('p'), type: 'point', x, y, standalone: true }; k.entities.push(p); } });
      pts.name = 'Points';
      const path = sk((k) => { const l = S.addLine(k, 0, 70, 100, 70); void l; });
      path.name = 'Path';
      m.actions.change('op.edit', () => {});
      await m.run('newPart');
      const pin = m.active(); pin.name = 'Pin';
      const ps = F.createFeature(pin, 'sketch', { plane: top, ...S.createSketchGeometry() }); S.addCircle(ps, 0, 0, 1.9); pin.features.push(ps);
      pin.features.push(F.createFeature(pin, 'extrude', { sketch: ps.id, depth: 15 }));
      m.actions.change('op.edit', () => {});
      m.actions.cancelEditing?.({ quiet: true });
      const proj = m.project;
      proj.assemblies.push({ id: 'asmT', name: 'Asm', components: [], mates: [] });
      await m.actions.switchDocument({ kind: 'assembly', id: 'asmT' });
      m.actions.cancelEditing?.({ quiet: true });
      m.actions.insertComponent(plate.id);
      m.actions.insertComponent(pin.id);
      const a = m.active();
      // The pin sits in the first hole: (10, 10).
      const p = a.components.find((c) => c.part === pin.id); p.position = [10, 10, 0];
      return a.components.length + ' ' + a.components.map((c) => c.name).join(',');
    })()

